VALUES ('club_vienna-the-bamboo-room', 'The Bamboo Room', 'vienna-the-bamboo-room', 'Mahjong social club in Vienna. Its own listings call open play "NMJL American" for all levels and teach American mahjong, with Mahjong 101 and 102 lessons, instructor-led guided play, skill-building series and happy-hour open play. Memberships and a gift card are sold on its site.', (SELECT id FROM City WHERE name = 'Vienna' AND state = 'VA'), '101 Church Street NW, Unit D, Vienna, VA 22180', 'https://thebambooroom.bamgoodtime.com', NULL, NULL, NULL, NULL, 1, 1, 1, 1, 0, 0, NULL, 'Open play, lessons and guided play most days (dates listed on the club site)', 'https://thebambooroom.bamgoodtime.com', '2026-10-11', 'ACTIVE')
